Create `.claude/hooks/lib/resolve-formatter.js`:

```javascript
const fs = require('fs');
const path = require('path');

const CACHE = new Map(); // Session-level cache

function findProjectRoot(filePath) {
  let dir = path.dirname(filePath);
  while (dir !== '/') {
    if (fs.existsSync(path.join(dir, 'package.json')) || 
        fs.existsSync(path.join(dir, 'pyproject.toml'))) {
      return dir;
    }
    dir = path.dirname(dir);
  }
  return process.cwd();
}

function resolveFormatter(filePath) {
  const ext = path.extname(filePath);
  const projectRoot = findProjectRoot(filePath);
  const cacheKey = `${projectRoot}:${ext}`;

  if (CACHE.has(cacheKey)) return CACHE.get(cacheKey);

  let result = { formatter: null, binary: null, args: [] };

  if (['.js', '.jsx', '.ts', '.tsx'].includes(ext)) {
    // Prefer local node_modules/.bin over npx
    if (fs.existsSync(path.join(projectRoot, 'biome.json'))) {
      const localBiome = path.join(projectRoot, 'node_modules/.bin/biome');
      result = { formatter: 'biome', binary: fs.existsSync(localBiome) ? localBiome : 'npx biome', args: ['check', '--write'] };
    } else if (fs.existsSync(path.join(projectRoot, '.prettierrc'))) {
      const localPrettier = path.join(projectRoot, 'node_modules/.bin/prettier');
      result = { formatter: 'prettier', binary: fs.existsSync(localPrettier) ? localPrettier : 'npx prettier', args: ['--write'] };
    }
  } else if (ext === '.py') {
    result = { formatter: 'ruff', binary: 'ruff', args: ['format'] };
  } else if (ext === '.go') {
    result = { formatter: 'gofmt', binary: 'gofmt', args: ['-w'] };
  }

  CACHE.set(cacheKey, result);
  return result;
}

module.exports = { resolveFormatter, findProjectRoot };
```

