Create `.claude/hooks/file-size-guard.js`:

```javascript
#!/usr/bin/env node
// file-size-guard.js - Block oversized file creation
// PreToolUse matcher: Write
// Exit 2 to block, Exit 0 to allow

const { isHookEnabled } = require('./lib/hook-profiles');

if (!isHookEnabled('file-size-guard')) process.exit(0);

const MAX_LINES = 800;
const EXEMPT_FILES = ['package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'Cargo.lock', 'go.sum'];

let input = '';
process.stdin.on('data', chunk => input += chunk);
process.stdin.on('end', () => {
  try {
    const data = JSON.parse(input);
    const filePath = data.tool_input?.file_path;
    const content = data.tool_input?.content || '';

    if (!filePath) process.exit(0);

    // Check exempt files
    const filename = filePath.split('/').pop();
    if (EXEMPT_FILES.includes(filename)) process.exit(0);
    if (filePath.includes('/generated/') || filePath.includes('.generated.')) process.exit(0);

    // Count lines
    const lineCount = content.split('\n').length;

    if (lineCount > MAX_LINES) {
      console.log(`BLOCKED: File exceeds ${MAX_LINES} lines (${lineCount} lines).`);
      console.log('Split into smaller, focused modules for better maintainability.');
      console.log(`File: ${filename}`);
      process.exit(2);
    }

    process.exit(0);
  } catch (e) {
    process.exit(0); // Don't block on parse errors
  }
});
```

