```javascript
#!/usr/bin/env node
// cost-tracker.js - Session cost telemetry
// Stop hook (async, non-blocking)
// Timeout: 10s

const fs = require('fs');
const path = require('path');

const PROJECT_DIR = process.env.CLAUDE_PROJECT_DIR || '.';
const COST_LOG = path.join(PROJECT_DIR, '.claude/sessions/cost-log.jsonl');

let input = '';
process.stdin.on('data', chunk => input += chunk);
process.stdin.on('end', () => {
  try {
    const data = JSON.parse(input);
    const entry = {
      timestamp: new Date().toISOString(),
      session_id: data.session_id || process.env.CLAUDE_SESSION_ID || 'unknown',
      tool_name: data.tool_name || 'session_end',
      estimated_tokens: estimateTokens(data),
      event_type: 'stop'
    };

    // Ensure directory exists
    fs.mkdirSync(path.dirname(COST_LOG), { recursive: true });

    // Append to log
    fs.appendFileSync(COST_LOG, JSON.stringify(entry) + '\n');
  } catch (e) {
    // Non-blocking, ignore errors
  }
  process.exit(0);
});

function estimateTokens(data) {
  // Rough estimation based on input/output size
  const inputSize = JSON.stringify(data.tool_input || {}).length;
  const outputSize = JSON.stringify(data.tool_output || {}).length;
  return Math.ceil((inputSize + outputSize) / 4);
}
```

